 * Counts the election described by `candidates` (all declared names) and
 * `ballots` (a list of `{ count, names }`, most to least preferred).
 *
 * Returns `{ rounds, winner }`, where `rounds` is a list of
 * `{ tally, exhausted, eliminated }` for each round counted, in order.
 * `tally` maps every candidate still continuing at that round to the number
 * of ballots that counted for them. `eliminated` is the name removed after
 * that round, or `null` for the round that ended the election. `winner` is
 * the winning name, or `null` when no candidate ever reached a majority.
 */
export function countElection(candidates, ballots) {
  let continuing = new Set(candidates)
  const history = []
  const rounds = []
  let winner = null

  for (;;) {
    const tally = new Map()
    for (const name of continuing) tally.set(name, 0)
    let exhausted = 0

    for (const ballot of ballots) {
      const choice = ballot.names.find((name) => continuing.has(name))
      if (choice === undefined) {
        exhausted += ballot.count
      } else {
        tally.set(choice, tally.get(choice) + ballot.count)
      }
    }

    history.push(tally)
    const activeTotal = [...tally.values()].reduce((a, b) => a + b, 0)

    let roundWinner = null
    for (const [name, votes] of tally) {
      if (votes * 2 > activeTotal) {
        roundWinner = name
        break
      }
    }

    if (roundWinner !== null) {
      rounds.push({ tally, exhausted, eliminated: null })
      winner = roundWinner
      break
    }

    if (activeTotal === 0) {
      rounds.push({ tally, exhausted, eliminated: null })
      break
    }

    const minVotes = Math.min(...tally.values())
    const fewest = [...tally.entries()].filter(([, votes]) => votes === minVotes).map(([name]) => name)
    const eliminated = pickEliminated(fewest, history)

    rounds.push({ tally, exhausted, eliminated })
    continuing.delete(eliminated)
  }

  return { rounds, winner }
