  const mode = process.argv[2]
  if (process.argv.length !== 3 || (mode !== 'rounds' && mode !== 'tally')) {
    process.stderr.write('error: usage: cli.js rounds|tally\n')
    process.exit(2)
  }

  const input = readStdin()

  let election
  try {
    election = parseElection(input)
  } catch (err) {
    if (err instanceof ParseError) {
      const message = err.line === null ? `error: ${err.message}\n` : `error: line ${err.line}: ${err.message}\n`
      process.stderr.write(message)
      process.exit(2)
    }
    throw err
  }

  const counted = countElection(election.candidates, election.ballots)
  const output = mode === 'rounds' ? formatRounds(counted) : formatTally(counted)
  process.stdout.write(output)
  process.exit(0)
}

